import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe that happens while `emit()` is
 * walking the set (a handler that attaches another handler) never mutates the
 * collection being iterated.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
/**
 * Next.js instrumentation hook. Runs once per server process before any
 * request is handled — the only sanctioned place to register the event-bus
 * subscribers and start the in-process job scheduler.
 */
export async function register(): Promise<void> {
  if (process.env.NEXT_RUNTIME !== "nodejs") return;

  const { registerEventHandlers } = await import(
    "@/server/services/event-registry"
  );
  const { startScheduler } = await import("@/server/jobs/scheduler");

  registerEventHandlers();
  startScheduler();
}

export function onRequestError(
  error: unknown,
  request: { path: string; method: string },
): void {
  console.error(
    `[taskflow] ${request.method} ${request.path} failed:`,
    error instanceof Error ? error.message : error,
  );
}
/** Subscribe/emit/unsubscribe, handler isolation and `subscriberCount`. */
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  emit,
  emitAndForget,
  onHandlerError,
  resetEventBus,
  subscribe,
  subscribeOnce,
  subscriberCount,
} from "@/lib/event-bus";
import type { IssueId, IsoTimestamp, ProjectId } from "@/types/common";
import type { TaskflowEventMap } from "@/types/event";
import { ALICE, ORG_A } from "../helpers/factories";

function issueCreated(
  title = "Fix the sign-up link",
): TaskflowEventMap["issue.created"] {
  return {
    orgId: ORG_A,
    actorId: ALICE,
    occurredAt: "2026-03-15T12:00:00.000Z" as IsoTimestamp,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    title,
    assigneeId: null,
    priority: "medium",
  };
}

afterEach(() => {
  resetEventBus();
});

describe("lib/event-bus", () => {
  it("delivers a payload to every subscriber of that type only", async () => {
    const onCreated = vi.fn();
    const onArchived = vi.fn();
    subscribe("issue.created", onCreated);
    subscribe("issue.archived", onArchived);

    await emit("issue.created", issueCreated());

    expect(onCreated).toHaveBeenCalledTimes(1);
    expect(onCreated.mock.calls[0]?.[0]).toMatchObject({ title: "Fix the sign-up link" });
    expect(onArchived).not.toHaveBeenCalled();
  });

  it("is a no-op when nothing subscribes", async () => {
    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("stops delivering after the returned unsubscribe is called", async () => {
    const handler = vi.fn();
    const off = subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    off();
    expect(subscriberCount("issue.created")).toBe(0);
    await emit("issue.created", issueCreated());
    expect(handler).not.toHaveBeenCalled();
  });

  it("delivers a `subscribeOnce` handler exactly once", async () => {
    const handler = vi.fn();
    subscribeOnce("issue.created", handler);

    await emit("issue.created", issueCreated("first"));
    await emit("issue.created", issueCreated("second"));

    expect(handler).toHaveBeenCalledTimes(1);
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("isolates a throwing handler: siblings still run and emit resolves", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", () => {
      throw new Error("handler exploded");
    });
    const survivor = vi.fn();
    subscribe("issue.created", survivor);

    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(survivor).toHaveBeenCalledTimes(1);
    expect(sink).toHaveBeenCalledTimes(1);
    expect(sink.mock.calls[0]?.[0]).toBe("issue.created");
  });

  it("reports a rejected async handler to the error sinks", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", async () => {
      await Promise.reject(new Error("async boom"));
    });

    await emit("issue.created", issueCreated());
    expect(sink).toHaveBeenCalledTimes(1);
  });

  it("awaits async handlers before resolving", async () => {
    const order: string[] = [];
    subscribe("issue.created", async () => {
      await new Promise((resolve) => setTimeout(resolve, 5));
      order.push("handler");
    });

    await emit("issue.created", issueCreated());
    order.push("after-emit");
    expect(order).toEqual(["handler", "after-emit"]);
  });

  it("emitAndForget returns synchronously but still delivers", async () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);

    expect(emitAndForget("issue.created", issueCreated())).toBeUndefined();
    await Promise.resolve();
    await Promise.resolve();
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it("counts each distinct handler once", () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);
    subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    subscribe("issue.created", vi.fn());
    expect(subscriberCount("issue.created")).toBe(2);
  });
});
/**
 * Domain events published by the service layer.
 *
 * Services stay decoupled from notifications, search, the audit log and
 * webhooks by announcing facts on the bus. If an event stops firing — or fires
 * with the wrong payload — every one of those concerns silently stops working,
 * which is why the contract is pinned here rather than through its consumers.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("events");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("issue.created", () => {
  it("is emitted once per created issue, carrying the actor and the issue", async () => {
    const seen = capture("issue.created");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Emit me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      title: "Emit me",
      assigneeId: tenant.userIds.admin,
      priority: "none",
    });
    expect(seen[0]?.occurredAt).toEqual(expect.any(String));
  });

  it("is not emitted when the create is rejected", async () => {
    const seen = capture("issue.created");

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toThrow();

    expect(seen).toHaveLength(0);
  });
});

describe("issue.status_changed", () => {
  it("carries both ends of the transition", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ from: "backlog", to: "in_progress" });
  });

  it("stays silent when the status did not actually move", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "No-op move" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "backlog",
    });

    expect(seen).toHaveLength(0);
  });
});

describe("issue.assigned", () => {
  it("reports the previous assignee alongside the new one", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Reassign me",
        assigneeId: tenant.userIds.member,
      }),
    );

    const seen = capture("issue.assigned");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      previousAssigneeId: tenant.userIds.member,
      assigneeId: tenant.userIds.admin,
    });
  });

  it("falls back to issue.updated when the issue is un-assigned", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["assigneeId"]);
  });
});

describe("comment.created", () => {
  it("carries the mentions resolved server-side", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss me" }),
    );

    const seen = capture("comment.created");
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Taking a look, @owner",
      parentId: null,
      mentionedUserIds: [],
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]?.mentionedUserIds).toEqual([tenant.userIds.owner]);
  });
});

describe("project.archived", () => {
  it("reports how many issues the cascade took with it", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Cascade",
      slug: "cascade",
      key: "CAS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Goes with it" }),
    );

    const seen = capture("project.archived");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]?.issuesArchived).toBe(1);
  });
});
